int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size);

int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
{
    FILE *f;
    SpectreDocument *document;

/* This is part of the build, it should at least compile on Windows */
#if _POSIX_C_SOURCE >= 200809L
    f = fmemopen((void*)data, size, "rb");
    if(f == NULL) return 0;
#endif

    document = spectre_document_new();
    if(document == NULL)
    {
        fclose(f);
        return 0;
    }

    spectre_document_load_from_stream(document, f);

    if(spectre_document_status(document))
    {
        spectre_document_free(document);
        fclose(f);
        return 0;
    }

    spectre_document_free(document);
    fclose(f);

    return 0;
}

#ifdef __cplusplus
}
#endif

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

/* fuzz target entry point, works without libFuzzer */

int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size);

int main(int argc, char **argv)
{
    FILE *f;
    char *buf = NULL;
    long siz_buf;

    if(argc < 2)
    {
        fprintf(stderr, "no input file\n");
        goto err;
    }

    f = fopen(argv[1], "rb");
    if(f == NULL)
    {
        fprintf(stderr, "error opening input file %s\n", argv[1]);
        goto err;
    }

    fseek(f, 0, SEEK_END);

    siz_buf = ftell(f);
    rewind(f);

    if(siz_buf < 1) goto err;

    buf = (char*)malloc((size_t)siz_buf);
    if(buf == NULL)
    {
        fprintf(stderr, "malloc() failed\n");
        goto err;
    }

    if(fread(buf, (size_t)siz_buf, 1, f) != 1)
    {
        fprintf(stderr, "fread() failed\n");
        goto err;
    }

    (void)LLVMFuzzerTestOneInput((uint8_t*)buf, (size_t)siz_buf);

err:
    free(buf);

    return 0;
}

